 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not out or not out[0]:
        return out
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    div = next(((r, row[0]) for r, row in enumerate(out)
                if all(v == row[0] for v in row) and row[0] != bg), None)
    if div is None:
        return out
    dr, dc = div
    cells = [(r, c, out[r][c]) for r in range(h) for c in range(w)
             if out[r][c] != bg and not (r == dr and out[r][c] == dc)]
    if not cells:
        return out
    rmin = min(r for r, _, _ in cells)
    rmax = max(r for r, _, _ in cells)
    if rmax < dr:
        shift = dr - 1 - rmax
        new_top, new_bottom = rmin + shift, rmax + shift
        for r, c, _ in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + shift][c] = v
        marker = new_top - 1
    elif rmin > dr:
        shift = dr + 1 - rmin
        new_top, new_bottom = rmin + shift, rmax + shift
        for r, c, _ in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + shift][c] = v
        marker = new_bottom + 1
    else:
        return out
    if 0 <= marker < h:
        out[marker] = [8] * w
    return out
"
